usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Evals.Runs.OutputItems.List(
		context.TODO(),
		"eval_id",
		"run_id",
		openai.EvalRunOutputItemListParams{
			After: param.NewOpt[string]("after"),
			Limit: param.NewOpt[int64](20),
			Status: param.NewOpt[openai.EvalsRunsOutputItemsListStatus](openai.EvalsRunsOutputItemsListStatusFail),
			Order: param.NewOpt[openai.EvalsRunsOutputItemsListOrder](openai.EvalsRunsOutputItemsListOrderAsc),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
